def main():
    with open(os.path.join(ROOT, "ads-copy.csv"), "w", newline="", encoding="utf-8-sig") as f:
        w = csv.writer(f)
        w.writerow(["ID", "Файл(ы)", "Тип", "Угол", "Оффер", "Основной текст (Primary text)", "Заголовок (Headline)", "Описание (Description)", "Кнопка (CTA)", "Ссылка (с UTM)"])
        for a in ADS:
            fn = a["file"] + ("_4x5.png / _9x16.png" if a["type"] == "картинка" else ".mp4")
            w.writerow([a["id"], fn, a["type"], a["angle"], a["offer"], a["primary"], a["headline"], a["desc"], a["cta"], URL.format(id=a["file"])])
    md = ["# Тексты объявлений и матрица теста", "",
          "Сгенерировано `tools/gen_copy.py` (правьте данные там и запускайте заново). Табличная версия для загрузки — `ads-copy.csv`.", "",
          "Ссылка для всех объявлений — лендинг `/trial-ru` (для казахоязычной аудитории — `/trial-kz`) с UTM-меткой по названию креатива.", "",
          "## Матрица теста", "", "| ID | Угол | Оффер | Хук | Визуал | «Почему сейчас» |", "|---|---|---|---|---|---|"]
    for a in ADS:
        md.append(f"| **{a['id']}** | {a['angle']} | {a['offer']} | {a['hook']} | {a['visual']} | {a['why']} |")
    md += ["", "Оффера: **A** — «пробный урок 3000 ₸» (цена сразу), **B** — «без обязательств» (цена только в кнопке/на лендинге), **C** — «диагностика»: «поймёте за 60 минут, его ли это», **D** — «ценность»: что входит в программу.", "",
           "## Тексты для Ads Manager", ""]
    for a in ADS:
        fn = a["file"] + ("_4x5.png (Лента) · _9x16.png (Stories/Reels)" if a["type"] == "картинка" else ".mp4 (Reels/Stories)")
        md += [f"### {a['id']} · {a['hook']}", "", f"- **Файл:** `{fn}`", f"- **Угол:** {a['angle']} · **Оффер:** {a['offer']}",
               f"- **Заголовок (≤40 зн.):** {a['headline']}", f"- **Описание:** {a['desc']}", f"- **Кнопка:** {a['cta']}",
               f"- **Запасные заголовки для A/B:** {' · '.join(a['alts'])}", "", "**Основной текст** (первые ~125 знаков видны до «ещё» — там уже хук и польза):", "",
               textwrap.indent(a["primary"], "> ", predicate=lambda l: True), ""]
    open(os.path.join(ROOT, "COPY-DECK.md"), "w", encoding="utf-8").write("\n".join(md))
    print("ok:", len(ADS), "ads")
main()
